import{_ as e,o as d,c as o,a7 as i}from"./chunks/framework.DjEbLKqE.js";const p=JSON.parse('{"title":"CAOSHI 技术文档","titleTemplate":"Java / Vue / SQL 笔记","description":"","frontmatter":{"layout":"home","title":"CAOSHI 技术文档","titleTemplate":"Java / Vue / SQL 笔记","hero":{"name":"CAOSHI 技术文档","text":"前端 · 后端 · 数据库","actions":[{"theme":"brand","text":"开始阅读","link":"/doc/web"},{"theme":"alt","text":"GitHub","link":"https://github.com/zzzaszz/docs"}]},"features":[{"icon":"🌱","title":"前端","details":"Vue3、Vite、npm、CSS 布局","link":"/doc/web"},{"icon":"🍃","title":"后端","details":"Spring Boot、Stream、EasyPOI","link":"/doc/svc"},{"icon":"🔌","title":"硬件","details":"ESP32-S3、GPIO、总线、LVGL","link":"/doc/hardware"},{"icon":"🗄️","title":"数据库 / 其他","details":"MySQL 索引、Linux、Git","link":"/doc/other"},{"icon":"🔧","title":"遇到的问题","details":"SQL Server、批量写入、Redis","link":"/doc/question"},{"icon":"🧰","title":"开发工具","details":"时区、时间戳、JSON 格式化","link":"/tools/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793774566000}'),a={name:"index.md"};function c(r,t,s,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[i('<h2 id="关于本站" tabindex="-1">关于本站 <a class="header-anchor" href="#关于本站" aria-label="Permalink to &quot;关于本站&quot;">​</a></h2><p>这是一个用 Markdown 写成的个人技术笔记站。平时在 Obsidian 里按主题记录前端、后端、数据库、硬件和踩坑经验，笔记保存后自动同步到 GitHub，再由 GitHub Actions 构建成现在看到的网页——不需要手动打包、上传或部署。</p><p>内容按「前端 / 后端 / 硬件 / 数据库」和「遇到的问题」分栏，另外放了一些日常用得到的小工具：时区转换、时间戳转换、JSON 格式化、图片与 Base64 互转、图片格式转换与压缩、二维码、UUID / 哈希 / JWT。</p><p>站点基于 VitePress 1.6 + Vue 3，使用 pnpm 构建，托管在 GitHub Pages；主题为自制，支持站内搜索、暗色模式、正文图片点击放大和标题按层级折叠。</p><h2 id="从笔记到网页的流程" tabindex="-1">从笔记到网页的流程 <a class="header-anchor" href="#从笔记到网页的流程" aria-label="Permalink to &quot;从笔记到网页的流程&quot;">​</a></h2><p>写笔记这一步做完，后面三步全自动完成：</p><table tabindex="0"><thead><tr><th>步骤</th><th>在哪里发生</th><th>做了什么</th></tr></thead><tbody><tr><td>1. 记笔记</td><td>本地 Obsidian</td><td>用 Markdown 按主题写笔记，图片直接粘贴到 <code>doc/static/</code></td></tr><tr><td>2. 自动提交推送</td><td>本地 Obsidian</td><td>obsidian-git 插件定时扫描改动，自动 <code>git commit</code> 并 <code>git push</code> 到 GitHub 仓库</td></tr><tr><td>3. 自动构建</td><td>GitHub Actions</td><td>监听 <code>main</code> 分支推送，安装依赖并执行 <code>pnpm docs:build</code></td></tr><tr><td>4. 发布上线</td><td>GitHub Pages</td><td>构建产物发布到 <code>gh-pages</code> 分支，由 GitHub Pages 对外提供访问</td></tr></tbody></table><p>展开说明：</p><ol><li><strong>本地记笔记</strong>：笔记就是普通的 Markdown 文件，按主题放在 <code>doc/</code> 下（<code>web.md</code>、<code>svc.md</code>、<code>other.md</code>、<code>hardware.md</code>、<code>question.md</code>），图片放在 <code>doc/static/</code>。在 Obsidian 里可以正常预览、搜索、链接，本质上就是本地文件。</li><li><strong>插件自动上传</strong>：Obsidian 的 obsidian-git 插件按插件里配置的间隔检查改动，发现变化就自动生成一条提交记录（形如 <code>vault backup: 2026-11-04 14:37:30</code>）并推送到 GitHub，全程不用手动敲 git 命令。</li><li><strong>GitHub 自动部署</strong>：仓库中的 <code>.github/workflows/deploy.yml</code> 监听 <code>main</code> 分支推送，用 Node 22 + pnpm 安装依赖、构建 VitePress、生成 <code>.nojekyll</code>，最后把构建产物发布到 <code>gh-pages</code> 分支。</li><li><strong>访问站点</strong>：GitHub Pages 读取 <code>gh-pages</code> 分支的静态文件对外提供访问。每次推送后等 Actions 跑完，页面就是最新的。</li></ol><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>说明</th></tr></thead><tbody><tr><td><code>doc/</code></td><td>前端、后端、数据库、硬件、常见问题等 Markdown 笔记与图片</td></tr><tr><td><code>tools/</code></td><td>在线小工具页面：时区、时间戳、JSON、图片转换 / 压缩、二维码、Base64、UUID / 哈希 / JWT</td></tr><tr><td><code>.vitepress/</code></td><td>站点配置与自定义主题：样式、图片查看器、标题折叠、各工具组件</td></tr><tr><td><code>.github/workflows/</code></td><td>GitHub Actions 自动部署配置</td></tr></tbody></table><p>源码与问题反馈见 <a href="https://github.com/zzzaszz/docs" target="_blank" rel="noreferrer">GitHub 仓库</a>。</p>',12)])])}const u=e(a,[["render",c]]);export{p as __pageData,u as default};
